import {demoData,reconcile,timestamp,money} from './engine.js';

// Public illustrations use the same clearly synthetic fixture as the interactive demo.
const sample=demoData(),results=reconcile(sample);
const counts={orders:sample.orders.length,ship:results.filter(r=>r.status==='ship').length,hold:results.filter(r=>r.status==='hold').length,review:results.filter(r=>r.status==='review').length};
const mesh=document.createElement('div');mesh.className='ambient-mesh';mesh.setAttribute('aria-hidden','true');mesh.innerHTML='<i class="ambient-orb"></i><i class="ambient-orb"></i><i class="ambient-orb"></i>';
document.body.prepend(mesh);const halo=document.createElement('div');halo.className='cursor-halo';halo.setAttribute('aria-hidden','true');document.body.append(halo);
const hero=document.querySelector('.hero'),heading=hero.querySelector('h1');heading.setAttribute('aria-label','Every payment. In its right place.');
const walker=document.createTreeWalker(heading,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
let wordIndex=0;for(const node of nodes){const fragment=document.createDocumentFragment();for(const word of node.textContent.split(/(\s+)/)){if(!word)continue;if(/^\s+$/.test(word)){fragment.append(word);continue;}const span=document.createElement('span');span.className='headline-word';span.textContent=word;span.setAttribute('aria-hidden','true');span.style.setProperty('--word-index',wordIndex++);fragment.append(span);}node.replaceWith(fragment);}
const times=sample.claims.map(c=>timestamp(c.at)).filter(Number.isFinite).sort((a,b)=>a-b);
const start=timestamp('2026-10-09T08:00'),end=timestamp('2026-10-09T22:00');
const points=Array.from({length:15},(_,index)=>{const time=start+(end-start)*index/14;const n=times.filter(t=>t<=time).length;return `${index*900/14},${110-n/times.length*90}`;});
hero.insertAdjacentHTML('afterend',`<section class="demo-observatory" aria-labelledby="observatory-title"><div class="observatory-top"><div><div class="eyebrow">SYNTHETIC SAMPLE · NOT LIVE BANK DATA</div><h2 id="observatory-title">The signal in the details.</h2><p>One fictional dispatch batch. Every recommendation is computed from the demo records, with uncertainty kept visible.</p></div><div class="demo-metrics">${[['orders','Orders'],['ship','Ship'],['hold','Hold'],['review','Review']].map(([key,label])=>`<div class="demo-metric"><strong data-demo-count="${counts[key]}">${counts[key]}</strong><span>${label.toUpperCase()}</span></div>`).join('')}</div></div><svg class="evidence-chart" viewBox="0 0 900 120" preserveAspectRatio="none" role="img" aria-label="Synthetic fixture: cumulative timestamped receipt claims during one fictional day; not live account activity"><defs><linearGradient id="activity-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#56dfc5" stop-opacity=".2"/><stop offset="100%" stop-color="#56dfc5" stop-opacity="0"/></linearGradient></defs><path class="chart-area" d="M0,120 L${points.join(' L')} L900,120 Z"/><polyline class="chart-line" points="${points.join(' ')}"/></svg><div class="chart-legend"><span>08:00 PKT</span><span>Synthetic timestamped receipt claims</span><span>22:00 PKT</span></div></section><p class="ticker-caption">FICTIONAL TRANSACTION EXAMPLES · NO PAYMENTS ARE SENT</p><div class="demo-ticker" aria-label="Fictional transaction examples"><div class="ticker-track"></div></div>`);
const track=document.querySelector('.ticker-track');for(let copy=0;copy<2;copy++){for(const row of results.slice(0,8)){const span=document.createElement('span');if(copy)span.setAttribute('aria-hidden','true');span.textContent=`DEMO #${row.id} · PKR ${money(row.order.due)} · ${row.status.toUpperCase()}  ✦`;track.append(span);}}
const reduced=matchMedia('(prefers-reduced-motion: reduce)'),fine=matchMedia('(hover: hover) and (pointer: fine)');
let frame=0,pointer=null,magnetic=null,disposed=false;
function paused(){return reduced.matches||document.hidden||document.getElementById('landing')?.hidden||document.body.classList.contains('motion-paused');}
function draw(){frame=0;if(disposed||paused())return;if(pointer&&fine.matches){halo.style.setProperty('--cursor-x',(pointer.x-150)+'px');halo.style.setProperty('--cursor-y',(pointer.y-150)+'px');}const depth=Math.min(scrollY,700)*.045;document.documentElement.style.setProperty('--hero-depth',fine.matches?depth+'px':'0px');}
function queue(){if(!frame&&!paused())frame=requestAnimationFrame(draw);}
function sync(){document.body.dataset.effectsPaused=String(paused());if(paused()){cancelAnimationFrame(frame);frame=0;document.documentElement.style.setProperty('--hero-depth','0px');halo.style.setProperty('--cursor-x','-1000px');if(magnetic)magnetic.style.transform='';}else queue();}
const controller=new AbortController(),signal=controller.signal;
if(fine.matches)document.addEventListener('pointermove',event=>{if(paused()||event.pointerType==='touch')return;pointer={x:event.clientX,y:event.clientY};const button=event.target.closest('.hero-actions .btn');if(magnetic&&magnetic!==button)magnetic.style.transform='';magnetic=button;if(button){const r=button.getBoundingClientRect();button.style.transform=`translate3d(${(event.clientX-r.left-r.width/2)*.1}px,${(event.clientY-r.top-r.height/2)*.12}px,0)`;}queue();},{passive:true,signal});
window.addEventListener('scroll',queue,{passive:true,signal});document.addEventListener('visibilitychange',sync,{signal});reduced.addEventListener('change',sync,{signal});
const mutation=new MutationObserver(sync);mutation.observe(document.body,{attributes:true,attributeFilter:['class']});
const observer=new IntersectionObserver(entries=>{for(const entry of entries){if(!entry.isIntersecting)continue;observer.unobserve(entry.target);if(paused())continue;const spans=[...entry.target.querySelectorAll('[data-demo-count]')],begin=performance.now();function count(now){const progress=Math.min(1,(now-begin)/850);for(const span of spans)span.textContent=Math.round(Number(span.dataset.demoCount)*(1-Math.pow(1-progress,3)));if(progress<1&&!paused())requestAnimationFrame(count);else for(const span of spans)span.textContent=span.dataset.demoCount;}requestAnimationFrame(count);}},{threshold:.25});observer.observe(document.querySelector('.demo-observatory'));
const tablist=document.querySelector('.scenario-tabs'),tabs=[...tablist.querySelectorAll('[role="tab"]')],panel=document.getElementById('scenario-stage');
function syncTabs(){for(const [index,tab] of tabs.entries()){tab.id='scenario-tab-'+index;tab.setAttribute('aria-controls',panel.id);tab.tabIndex=tab.getAttribute('aria-selected')==='true'?0:-1;}const active=tabs.find(tab=>tab.getAttribute('aria-selected')==='true');if(active)panel.setAttribute('aria-labelledby',active.id);}
tablist.addEventListener('click',()=>queueMicrotask(syncTabs),{signal});
tablist.addEventListener('keydown',event=>{const index=tabs.indexOf(event.target);if(index<0||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length;tabs[next].click();tabs[next].focus();syncTabs();},{signal});syncTabs();
window.addEventListener('pageshow',event=>{if(event.persisted)sync();},{signal});
window.addEventListener('pagehide',event=>{if(event.persisted){cancelAnimationFrame(frame);frame=0;return;}disposed=true;controller.abort();mutation.disconnect();observer.disconnect();cancelAnimationFrame(frame);},{once:true});sync();
